    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+1)*40,0.13,1.4,0.95]
  ];
  let act=0,inh=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    act+=Math.sin(d*f-t*sp)*w;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
