  act/=8;inh/=8;
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1)+Math.sin(wx*0.07-wy*0.05+t*1.5)*0.5+Math.sin(wx*0.11+wy*0.08-t*2)*0.25)/2.75;
  const cx=240,cy=120,dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2+t*0.8)*0.3)*0.35;
  const c2x=350+Math.sin(t*0.2)*50,c2y=80+Math.cos(t*0.3)*30;
