  const raw=act-inh*0.65+bg*0.35+spiral+sp2+cell*0.3;
  const reaction=Math.tanh(raw*2.8);
  const edge=1-reaction*reaction;
  const sharp=Math.pow(Math.abs(reaction),0.55)*Math.sign(reaction);
  const glow=Math.exp(-edge*edge*10)*0.45;
  const v=sharp*0.65+glow*0.35;
